-- public.hod_may(p_world uuid, c creature, p_kind text, p_level integer, p_dir text, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.hod_may(p_world uuid, c creature, p_kind text, p_level integer, p_dir text, p_x integer, p_y integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  select case p_kind
    when 'wall' then coalesce((select worker_build_open(c, coalesce(ch.material, w.material), coalesce(ch.type, w.type), null, null)
                                 from wall w
                                 left join wall_change ch on ch.world_id = w.world_id and ch.level = w.level and ch.dir = w.dir
                                                         and ch.x = w.x and ch.y = w.y
                                where w.world_id = p_world and w.level = p_level and w.dir = p_dir and w.x = p_x and w.y = p_y), true)
    when 'floor' then coalesce((select worker_build_open(c, f.material, null, f.kind, f.hand) from floor_tile f
                                 where f.world_id = p_world and f.level = p_level and f.x = p_x and f.y = p_y), true)
    when 'column' then coalesce((select worker_build_open(c, bc.material, null, null, null) from building_column bc
                                  where bc.world_id = p_world and bc.level = p_level and bc.x = p_x and bc.y = p_y), true)
    when 'span' then coalesce((select bool_and(worker_gate_open(c, skill_gate_of('bridge', b.kind)))
                                 from bridge_span sp join bridge b on b.world_id = sp.world_id and b.id = sp.bridge
                                where sp.world_id = p_world and sp.x = p_x and sp.y = p_y and not span_done(sp.needed)), true)
    else true end
$function$
